import java.util.*;

public class Main {
    static class AutoConfigCandidate {
        final String name;
        final String requiredClass;
        final String missingBean;
        final String propertyName;
        final String propertyValue;
        final String beanName;

        AutoConfigCandidate(String name, String requiredClass, String missingBean,
                            String propertyName, String propertyValue, String beanName) {
            this.name = name;
            this.requiredClass = requiredClass;
            this.missingBean = missingBean;
            this.propertyName = propertyName;
            this.propertyValue = propertyValue;
            this.beanName = beanName;
        }
    }

    static class MiniBootSelector {
        final Set<String> classpath;
        final Set<String> beans;
        final Map<String, String> properties;
        final List<String> report = new ArrayList<>();

        MiniBootSelector(Set<String> classpath, Set<String> beans, Map<String, String> properties) {
            this.classpath = new LinkedHashSet<>(classpath);
            this.beans = new LinkedHashSet<>(beans);
            this.properties = new LinkedHashMap<>(properties);
        }

        void apply(List<AutoConfigCandidate> imports, Set<String> excludes) {
            Map<String, AutoConfigCandidate> deduplicated = new LinkedHashMap<>();
            for (AutoConfigCandidate candidate : imports) deduplicated.putIfAbsent(candidate.name, candidate);
            for (AutoConfigCandidate candidate : deduplicated.values()) {
                if (excludes.contains(candidate.name)) {
                    report.add("EXCLUDE " + candidate.name);
                    continue;
                }
                if (candidate.requiredClass != null && !classpath.contains(candidate.requiredClass)) {
                    report.add("NO_MATCH " + candidate.name + " missing class " + candidate.requiredClass);
                    continue;
                }
                if (candidate.missingBean != null && beans.contains(candidate.missingBean)) {
                    report.add("NO_MATCH " + candidate.name + " user bean " + candidate.missingBean);
                    continue;
                }
                if (candidate.propertyName != null && !candidate.propertyValue.equals(properties.get(candidate.propertyName))) {
                    report.add("NO_MATCH " + candidate.name + " property " + candidate.propertyName);
                    continue;
                }
                beans.add(candidate.beanName);
                report.add("MATCH " + candidate.name + " -> " + candidate.beanName);
            }
        }
    }

    static List<AutoConfigCandidate> importsFile() {
        return List.of(
            new AutoConfigCandidate("DataSourceAutoConfiguration", "javax.sql.DataSource", "dataSource", null, null, "dataSource"),
            new AutoConfigCandidate("AcmeClientAutoConfiguration", "com.acme.Client", "acmeClient", "acme.enabled", "true", "acmeClient"),
            new AutoConfigCandidate("WebMvcAutoConfiguration", "jakarta.servlet.Servlet", null, null, null, "dispatcherServlet"),
            new AutoConfigCandidate("DataSourceAutoConfiguration", "javax.sql.DataSource", "dataSource", null, null, "dataSource")
        );
    }

    public static void main(String[] args) {
        MiniBootSelector normal = new MiniBootSelector(
            Set.of("javax.sql.DataSource", "com.acme.Client", "jakarta.servlet.Servlet"),
            Set.of(),
            Map.of("acme.enabled", "true")
        );
        normal.apply(importsFile(), Set.of("WebMvcAutoConfiguration"));
        System.out.println("case1 beans=" + normal.beans);
        System.out.println("case1 report=" + normal.report);
        assert normal.beans.equals(new LinkedHashSet<>(List.of("dataSource", "acmeClient")));

        MiniBootSelector userOverride = new MiniBootSelector(
            Set.of("javax.sql.DataSource"),
            Set.of("dataSource"),
            Map.of()
        );
        userOverride.apply(importsFile(), Set.of());
        System.out.println("case2 beans=" + userOverride.beans + ", backedOff=" + userOverride.report.get(0).contains("user bean"));
        assert userOverride.beans.equals(new LinkedHashSet<>(List.of("dataSource")));

        MiniBootSelector missingClass = new MiniBootSelector(Set.of(), Set.of(), Map.of());
        missingClass.apply(importsFile(), Set.of());
        System.out.println("case3 beans=" + missingClass.beans + ", firstReason=" + missingClass.report.get(0));
        assert missingClass.beans.isEmpty();
    }
}
